	/** 
	 * jumpstart the process by instantiating2 Contract
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		contractId = ContractService.getContractInstance()
		.createContract( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ContractService.getContractInstance()
				.createContract( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.contractSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Contract : " + successValue.getContractId());
							  if (successValue.getContractId().equals(contractId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfContractList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Contract test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on contract consumed")
					);
			subscriber.contractSubscribe( contractId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Contract : " + successValue.getContractId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfContractList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on contract for contractId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Contract. 
	 */
	protected Contract read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Contract" );

		Contract entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Contract with primary key" );
		msg.append( contractId );
		
		ContractFetchOneSummary fetchOneSummary = new ContractFetchOneSummary( contractId );

		try {
			entity = ContractService.getContractInstance().getContract( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Contract " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Contract.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Contract." );

		StringBuilder msg = new StringBuilder( "Failed to update a Contract : " );        
		Contract entity = read();
		UpdateContractCommand command = generateUpdateCommand();
		command.setContractId(entity.getContractId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Contract." );

			// for use later on...
			contractId = entity.getContractId();

			ContractService proxy = ContractService.getContractInstance();  

			proxy.updateContract( command ).get();

			LOGGER.info( "-- Successfully saved Contract - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + contractId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Contract.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Contract." );

		Contract entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Contract with id " + contractId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Contract with id " + contractId );

			throw e;
		}

		try{
			ContractService.getContractInstance().delete( new DeleteContractCommand( entity.getContractId() ) ).get();
			LOGGER.info( "-- Successfully deleted Contract with id " + contractId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Contract with id " + contractId );

			throw e;
		}
	}

	/**
	 * get all Contracts.
	 */
	protected List<Contract> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Contracts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Contract : " );        
		List<Contract> collection  = new ArrayList<>();

		try {
			// call the static get method on the ContractService
			collection = ContractService.getContractInstance().getAllContract();
			assertNotNull( collection, "An Empty collection of Contract was incorrectly returned.");
			
			// Now print out the values
			Contract entity = null;            
			Iterator<Contract> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getContractId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

